#!/usr/bin/env node
//
// Generate packages/coding-agent/src/embedded-assets.generated.ts.
//
// Standalone binaries (make bun / make deno) read theme, export-html, docs,
// examples, README, CHANGELOG, and package.json from an
// extraction directory rather than from files shipped next to the executable.
// This script inlines those files into a generated module that the runtime
// (src/standalone-assets.ts) extracts to a cache directory at startup.
//
// The generated file is gitignored; it is regenerated by the coding-agent
// build and by the root `npm run check` before tsgo runs.

import { createHash } from "node:crypto";
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, resolve } from "node:path";

const packageDir = resolve(import.meta.dirname, "../packages/coding-agent");
const outputPath = join(packageDir, "src", "embedded-assets.generated.ts");

// Relative path under the package root -> path on disk. Keys are written
// verbatim into the extracted layout used by standalone binaries.
const inputs = [
	["package.json", join(packageDir, "package.json")],
	["README.md", join(packageDir, "README.md")],
	["CHANGELOG.md", join(packageDir, "CHANGELOG.md")],
	...collectDir("theme", join(packageDir, "src/modes/interactive/theme")),
	...collectDir("export-html", join(packageDir, "src/core/export-html")),
	...collectDir("docs", join(packageDir, "docs")),
	...collectDir("examples", join(packageDir, "examples")),
];

// Skip hidden files and directories (e.g. .gitignore, .DS_Store).
function collectDir(keyPrefix, dirPath) {
	const entries = [];
	const walk = (dir) => {
		for (const name of readdirSync(dir)) {
			if (name === "node_modules" || name.startsWith(".")) continue;
			const fullPath = join(dir, name);
			if (statSync(fullPath).isDirectory()) {
				walk(fullPath);
			} else {
				entries.push([`${keyPrefix}/${relative(dirPath, fullPath)}`, fullPath]);
			}
		}
	};
	if (statSync(dirPath).isDirectory()) walk(dirPath);
	return entries;
}

const entries = [];
const hashes = [];
for (const [key, filePath] of inputs) {
	const content = readFileSync(filePath);
	hashes.push(`${key}:${createHash("sha256").update(content).digest("hex")}`);
	entries.push([key, content.toString("base64")]);
}

const cacheKey = createHash("sha256").update(hashes.sort().join("\n")).digest("hex").slice(0, 16);

const CHUNK_SIZE = 800_000;

function quoteChunks(value) {
	if (value.length <= CHUNK_SIZE) return `"${value}"`;
	const chunks = [];
	for (let i = 0; i < value.length; i += CHUNK_SIZE) {
		chunks.push(`\t\t"${value.slice(i, i + CHUNK_SIZE)}"`);
	}
	return chunks.join(" +\n");
}

const lines = [
	"/* Generated by scripts/generate-embedded-assets.mjs. Do not edit. */",
	"",
	`export const EMBEDDED_ASSETS_CACHE_KEY = "${cacheKey}";`,
	"",
	"export const EMBEDDED_ASSETS: Record<string, string> = {",
];
for (const [key, value] of entries) {
	lines.push(`\t${JSON.stringify(key)}: ${quoteChunks(value)},`);
}
lines.push("};");
lines.push("");

writeFileSync(outputPath, lines.join("\n"));
console.log(`Wrote ${outputPath} (${entries.length} files, ${(Buffer.byteLength(lines.join("\n"), "utf8") / 1e6).toFixed(1)}MB)`);
